// OLX
async function fetchOffersFromOLX(query) {
    const formattedQuery = encodeURIComponent(query).replace(/%20/g, '-');
    const url = `https://www.olx.pl/oferty/q-${formattedQuery}/?search%5Border%5D=created_at:desc`;
    try {
        const { data } = await axios.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' }, timeout: 10000 });
        const $ = cheerio.load(data);
        const offers = [];
        let stateData = null;
        $('script').each((i, el) => {
            const t = $(el).html();
            if (t.includes('window.__PRERENDERED_STATE__')) {
                const m = t.match(/window\.__PRERENDERED_STATE__\s*=\s*"(.+?)";/);
                if (m) try { stateData = JSON.parse(m[1].replace(/\\"/g, '"').replace(/\\\\/g, '\\')); } catch(e){}
                if (!stateData) { const m2 = t.match(/window\.__PRERENDERED_STATE__\s*=\s*({.+?});/); if(m2) try{stateData=JSON.parse(m2[1])}catch(e){} }
            }
        });
        if (stateData?.listing?.listing?.ads) {
            stateData.listing.listing.ads.forEach(ad => {
                if (!ad.url) return;
                let img = ad.photos?.[0]?.link ? ad.photos[0].link.replace('{width}', '600').replace('{height}', '400') : ad.photos?.[0];
                let priceRaw = 0; let priceDisplay = 'Brak ceny';
                if (ad.price) {
                    if (ad.price.regularPrice) { priceRaw = ad.price.regularPrice.value; priceDisplay = ad.price.displayValue; }
                    else if (ad.price.displayValue) { priceDisplay = ad.price.displayValue; priceRaw = parsePrice(ad.price.displayValue); }
                    if (ad.price.negotiable) priceDisplay += ' (Do negocjacji)';
                }
                const params = ad.params ? ad.params.filter(p => p.key !== 'price').map(p => `**${p.name}:** ${p.value}`) : [];
                offers.push({
                    id: ad.url, title: ad.title, priceRaw, priceDisplay, url: ad.url, imageUrl: img,
                    location: ad.location?.city?.name || 'PL', description: ad.description ? ad.description.replace(/<[^>]*>?/gm, '') : '', details: params
                });
            });
            STATS.scannedAds += offers.length;
            return offers;
        }
        return [];
    } catch (e) { STATS.errors++; log('ERROR', `OLX Scraper: ${e.message}`); return []; }
}

