            const title = imgEl.attr('alt') || 'Oferta Vinted';
            let link = linkEl.attr('href');
            if (link && !link.startsWith('http')) link = `https://www.vinted.pl${link}`;
            let priceDisplay = priceEl.text().trim() || 'Brak ceny';
            let priceRaw = parsePrice(priceDisplay);
            if (link) {
                offers.push({ id: link, title: title, priceRaw, priceDisplay, url: link, imageUrl: imgEl.attr('src') || null, location: 'Vinted', description: 'Oferta Vinted', details: [] });
            }
        });
        STATS.scannedAds += offers.length;
        return offers;
    } catch (e) { STATS.errors++; log('ERROR', `Vinted Scraper: ${e.message}`); return []; }
}

// ALLEGRO (Best Effort)
async function fetchOffersFromAllegro(query) {
    const formattedQuery = encodeURIComponent(query).replace(/%20/g, '+');
    const url = `https://allegro.pl/listing?string=${formattedQuery}&order=n`;
    try {
        const { data } = await axios.get(url, {
            headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36' },
            timeout: 10000
        });
        const $ = cheerio.load(data);
        const offers = [];
        
        $('article[data-analytics-view-custom-id]').each((i, el) => {
            if (i > 5) return;
            const titleEl = $(el).find('h2 a');
            if (!titleEl.length) return;
            
            const title = titleEl.text().trim();
            const link = titleEl.attr('href');
            const priceEl = $(el).find('[aria-label*="Cena"]');
            let priceDisplay = priceEl.text().trim() || 'Brak ceny';
            let priceRaw = parsePrice(priceDisplay);
            
            // Clean Image
            let img = $(el).find('img').first().attr('src');
            
            offers.push({
                id: link,
                title: title,
                priceRaw: priceRaw,
                priceDisplay: priceDisplay,
                url: link,
                imageUrl: img,
                location: 'Allegro',
                description: 'Oferta Allegro',
                details: []
            });
        });
        STATS.scannedAds += offers.length;
        return offers;
    } catch (e) {
        STATS.errors++;
        // log('ERROR', `Allegro Scraper: ${e.message}`); // Silent fail
        return [];
    }
}

async function runBotCycle(force = false) {
    // FIX: Jeśli wymuszenie (force=true), ignorujemy isScanning
    if ((!STATE.isRunning && !force) || (STATE.isScanning && !force)) {
        if (STATE.isScanning && (Date.now() - STATE.lastScanTime > 300000)) { log('WARN', 'Auto-Reset flagi skanera.'); STATE.isScanning = false; }
        return;
    }
    
    if (force) STATE.isScanning = false; // Hard reset dla pewności

    STATE.isScanning = true;
    STATE.lastScanTime = Date.now();

    try {
        for (const group of db.groups) {
            const channel = await client.channels.fetch(group.channelId).catch(() => null);
            if (!channel) continue;
            for (const topic of group.topics) {
                await new Promise(r => setTimeout(r, 2500));
                
                // WYBÓR SCRAPERA
                let offers = [];
                let embedColor = CONFIG.EMBED_COLOR;
                
                if (topic.platform === 'vinted') {
                    offers = await fetchOffersFromVinted(topic.query);
                    embedColor = CONFIG.VINTED_COLOR;
                } else if (topic.platform === 'allegro') {
                    offers = await fetchOffersFromAllegro(topic.query);
                    embedColor = CONFIG.ALLEGRO_COLOR;
                } else {
                    offers = await fetchOffersFromOLX(topic.query);
                }

                for (const offer of offers.reverse()) {
                    if (db.seenOffers.has(offer.url)) continue;
                    if (topic.minPrice && offer.priceRaw < topic.minPrice) { STATS.filteredAds++; db.seenOffers.add(offer.url); continue; }
                    if (topic.maxPrice && offer.priceRaw > topic.maxPrice) { STATS.filteredAds++; db.seenOffers.add(offer.url); continue; }
                    const allAnti = [...topic.antiPhrases, ...db.globalAntiPhrases];
                    if (allAnti.some(bad => offer.title.toLowerCase().includes(bad))) { STATS.filteredAds++; db.seenOffers.add(offer.url); continue; }

                    const embed = new EmbedBuilder().setColor(embedColor).setTitle(offer.title).setURL(offer.url)
                        .setDescription(`||${offer.description.substring(0, 300)}...||`)
                        .addFields({ name: 'Cena', value: `\`\`\`css\n${offer.priceDisplay}\n\`\`\``, inline: true }, { name: 'Lokalizacja', value: `${offer.location}`, inline: true })
                        .setFooter({ text: `FlipZone • ${topic.query} [${topic.platform || 'OLX'}]` }).setTimestamp();
                    
                    if (offer.details.length > 0) embed.addFields({ name: 'Szczegóły', value: offer.details.slice(0, 6).join('\n'), inline: false });
                    if (offer.imageUrl) embed.setThumbnail(offer.imageUrl);

                    const row = new ActionRowBuilder().addComponents(
                        new ButtonBuilder().setLabel('Otwórz').setStyle(ButtonStyle.Link).setURL(offer.url),
                        new ButtonBuilder().setCustomId('btn_add_deal').setLabel('🔥 Okazja').setStyle(ButtonStyle.Success)
                    );
                    if (topic.customButton) row.addComponents(new ButtonBuilder().setLabel(topic.customButton.label).setStyle(ButtonStyle.Link).setURL(topic.customButton.url));
                    
                    const content = topic.pingId ? `🔔 <@${topic.pingId}>` : '';
                    await channel.send({ content, embeds: [embed], components: [row] });
                    db.seenOffers.add(offer.url);
                    STATS.sentAds++;
                    log('INFO', `Wysłano [${topic.platform || 'OLX'}]: ${offer.title}`);
                }
            }
        }
    } catch (e) { log('ERROR', `Cycle: ${e.message}`); } 
    finally { STATE.isScanning = false; }
}

