client.on(Events.InteractionCreate, async interaction => {
    if (interaction.isChatInputCommand()) {
        const { commandName } = interaction;
        if (commandName === 'initialize') {
            await interaction.deferReply();
            const guild = interaction.guild;
            let rUnver = guild.roles.cache.find(r => r.name === 'FlipZone: Unverified') || await guild.roles.create({ name: 'FlipZone: Unverified', color: 0x95a5a6 });
            let rVer = guild.roles.cache.find(r => r.name === 'FlipZone: Verified') || await guild.roles.create({ name: 'FlipZone: Verified', color: 0x2ecc71, permissions: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
            let rStaff = guild.roles.cache.find(r => r.name === 'FlipZone: Staff') || await guild.roles.create({ name: 'FlipZone: Staff', color: 0xe74c3c, permissions: [PermissionsBitField.Flags.Administrator] });
            db.verification.unverifiedRoleId = rUnver.id; db.verification.verifiedRoleId = rVer.id; db.tickets.staffRoleId = rStaff.id;
            const vCh = guild.channels.cache.get(SERVER_MAP.VERIFY);
            if(vCh) await vCh.permissionOverwrites.set([{id:guild.id,deny:[PermissionsBitField.Flags.ViewChannel]},{id:rUnver.id,allow:[PermissionsBitField.Flags.ViewChannel],deny:[PermissionsBitField.Flags.SendMessages]},{id:rVer.id,deny:[PermissionsBitField.Flags.ViewChannel]}]);
            interaction.editReply({ content: `✅ **System Gotowy!**\nRole utworzone.` });
        }
        if (commandName === 'clear') {
             const n = interaction.options.getInteger('amount');
             await interaction.channel.bulkDelete(n, true);
             return interaction.reply({content:`Usunięto ${n}`, ephemeral:true});
        }
        if (commandName === 'nuke') {
            interaction.reply({content: 'Nuking...', ephemeral: true});
            const c = await interaction.channel.clone();
            interaction.channel.delete();
            c.send('https://media.giphy.com/media/HhTXt43PkqX9m/giphy.gif');
        }
    }

    if (interaction.isButton()) {
        if (interaction.customId === 'btn_create_ticket') {
            const ch = await interaction.guild.channels.create({
                name: `ticket-${interaction.user.username}`,
                type: ChannelType.GuildText,
                parent: db.tickets.categoryId,
                permissionOverwrites: [{ id: interaction.guild.id, deny: [PermissionsBitField.Flags.ViewChannel] }, { id: interaction.user.id, allow: [PermissionsBitField.Flags.ViewChannel] }, { id: client.user.id, allow: [PermissionsBitField.Flags.ViewChannel] }]
            });
            const staffRole = interaction.guild.roles.cache.get(db.tickets.staffRoleId) || interaction.guild.roles.cache.find(r => r.name === 'FlipZone: Staff');
            if (staffRole) await ch.permissionOverwrites.edit(staffRole.id, { ViewChannel: true, SendMessages: true });
            
            const row = new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('btn_close_ticket').setLabel('Zamknij').setStyle(ButtonStyle.Danger));
            ch.send({ content: `<@${interaction.user.id}> ${staffRole ? `<@&${staffRole.id}>` : ''}`, embeds: [new EmbedBuilder().setDescription('Opisz problem.').setColor(0x2ecc71)], components: [row] });
            return interaction.reply({ content: `Otwarto: <#${ch.id}>`, ephemeral: true });
        }
        if (interaction.customId === 'btn_close_ticket') {
            interaction.reply({content: 'Zamykanie...', ephemeral: true});
            setTimeout(() => interaction.channel.delete(), 3000);
        }
        if (interaction.customId === 'btn_add_deal') {
            if(!db.dealsChannelId) return interaction.reply({content: 'Brak kanału okazji', ephemeral: true});
            const ch = await client.channels.fetch(db.dealsChannelId);
            const row = new ActionRowBuilder().addComponents(new ButtonBuilder().setLabel('Idź').setStyle(ButtonStyle.Link).setURL(interaction.message.embeds[0].url));
            ch.send({ content: `🔥 Okazja od <@${interaction.user.id}>`, embeds: [interaction.message.embeds[0]], components: [row] });
            interaction.reply({ content: '✅', ephemeral: true });
        }
        if (interaction.customId === 'btn_start_verify') {
            const a = Math.floor(Math.random()*10), b = Math.floor(Math.random()*10);
            const modal = new ModalBuilder().setCustomId(`verify_${a+b}`).setTitle('Weryfikacja');
            modal.addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('ans').setLabel(`${a}+${b}=?`).setStyle(TextInputStyle.Short).setRequired(true)));
            interaction.showModal(modal);
        }
    }
    
    if (interaction.isModalSubmit() && interaction.customId.startsWith('verify_')) {
        const expected = interaction.customId.split('_')[1];
        if (interaction.fields.getTextInputValue('ans') === expected) {
            const rUnver = db.verification.unverifiedRoleId ? interaction.guild.roles.cache.get(db.verification.unverifiedRoleId) : interaction.guild.roles.cache.find(r => r.name === 'FlipZone: Unverified');
            const rVer = db.verification.verifiedRoleId ? interaction.guild.roles.cache.get(db.verification.verifiedRoleId) : interaction.guild.roles.cache.find(r => r.name === 'FlipZone: Verified');
            if(rUnver) await interaction.member.roles.remove(rUnver);
            if(rVer) await interaction.member.roles.add(rVer);
            interaction.reply({ content: '✅ Zweryfikowano!', ephemeral: true });
            discordLog('Weryfikacja', `Użytkownik ${interaction.user.tag} zweryfikowany.`, 0x2ecc71);
        } else {
            interaction.reply({ content: '❌ Błąd.', ephemeral: true });
        }
    }
});

